.hero-text p{
  font-size:1.05rem;
  max-width:480px;
  margin-bottom:36px;
  color:var(--ink-soft);
}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap;align-items:center}

.btn{
  display:inline-flex;align-items:center;gap:8px;
  padding:14px 26px;
  border-radius:999px;
  font-size:13px;font-weight:600;
  letter-spacing:.04em;
  transition:all var(--t);
  cursor:pointer;
}
.btn-primary{background:var(--ink);color:#fff}
.btn-primary:hover{background:var(--accent);transform:translateY(-1px);box-shadow:var(--shadow)}
.btn-ghost{color:var(--ink)}
.btn-ghost:hover{color:var(--accent)}

.hero-meta{
  display:flex;gap:40px;
  padding:24px 0;
  border-top:1px solid var(--line);
}
.hero-meta div{display:flex;flex-direction:column;gap:4px}
.hero-meta strong{
  font-family:'Fraunces',serif;
  font-size:2rem;font-weight:500;
}
.hero-meta span{font-size:11px;text-transform:uppercase;letter-spacing:.18em;color:var(--muted)}

.scroll-cue{
  position:absolute;bottom:30px;left:50%;
  transform:translateX(-50%);
  font-size:10px;text-transform:uppercase;
  letter-spacing:.3em;color:var(--muted);
  display:flex;flex-direction:column;align-items:center;gap:10px;
}
.scroll-cue span{
  width:1px;height:40px;background:var(--ink);
  animation:cue 2s ease-in-out infinite;
  transform-origin:top;
}
@keyframes cue{
  0%,100%{transform:scaleY(.3);opacity:.4}
  50%{transform:scaleY(1);opacity:1}
}

/* ---------- Section heads ---------- */
.section-head{
  display:flex;align-items:end;justify-content:space-between;
  margin-bottom:44px;gap:24px;flex-wrap:wrap;
}
.section-head h2{margin-top:6px}
.section-head.light{color:#fff}
.section-head.light h2{color:#fff}

.link-arrow{
  font-size:13px;font-weight:500;
  border-bottom:1px solid var(--ink);
  padding-bottom:2px;
  transition:color var(--t),border-color var(--t),gap var(--t);
}
.link-arrow:hover{color:var(--accent);border-color:var(--accent)}
.link-arrow.light{color:#fff;border-color:#fff}

/* ---------- Categories ---------- */
.categories{padding:100px 0 30px}
.cat-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:16px;
}
.cat-card{
  position:relative;
  aspect-ratio:3/4;
  border-radius:var(--radius-lg);
  overflow:hidden;
  display:flex;flex-direction:column;justify-content:space-between;
  padding:20px;
  color:#fff;
  transition:transform var(--t);
  isolation:isolate;
}
.cat-card::before{
  content:'';position:absolute;inset:0;z-index:-1;
  transition:transform .8s cubic-bezier(.2,.8,.2,1);
  background-size:cover;background-position:center;
}
.cat-card::after{
  content:'';position:absolute;inset:0;z-index:-1;
  background:linear-gradient(180deg,rgba(0,0,0,.05) 30%,rgba(0,0,0,.55) 100%);
}
.cat-card:hover::before{transform:scale(1.06)}
.cat-1::before{background-image:linear-gradient(135deg,#a89580,#5e4d3a)}
.cat-2::before{background-image:linear-gradient(135deg,#c9b9a1,#7a6850)}
.cat-3::before{background-image:linear-gradient(135deg,#3a3530,#1a1a1a)}
.cat-4::before{background-image:linear-gradient(135deg,#dbc8af,#9c8669)}
.cat-tag{
  font-size:11px;text-transform:uppercase;letter-spacing:.2em;
  padding:6px 10px;background:rgba(255,255,255,.18);
  backdrop-filter:blur(8px);border-radius:999px;
  align-self:flex-start;
}
.cat-name{
  font-family:'Fraunces',serif;
  font-size:1.6rem;font-weight:500;
}

/* ---------- Featured products ---------- */
.featured{padding:100px 0}
.filter-tabs{display:flex;gap:8px;background:var(--bg-alt);padding:5px;border-radius:999px}
.filter-tabs button{
  padding:8px 18px;
  font-size:13px;font-weight:500;
  border-radius:999px;
  color:var(--ink-soft);
  transition:all var(--t);
}
.filter-tabs button:hover{color:var(--ink)}
.filter-tabs button.active{background:var(--ink);color:#fff}

.product-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:32px 24px;
}
.product{
  display:flex;flex-direction:column;
  cursor:pointer;
  opacity:0;transform:translateY(20px);
  animation:rise .7s var(--t) forwards;
}
@keyframes rise{to{opacity:1;transform:none}}
.product-img{
  position:relative;
  aspect-ratio:4/5;
  border-radius:var(--radius);
  overflow:hidden;
  background:var(--bg-alt);
  margin-bottom:14px;
}
.product-img-inner{
  position:absolute;inset:0;
  background-size:cover;background-position:center;
  transition:transform .8s cubic-bezier(.2,.8,.2,1);
}
.product:hover .product-img-inner{transform:scale(1.05)}
.product-badge{
  position:absolute;top:12px;left:12px;
  background:#fff;color:var(--ink);
  font-size:10px;text-transform:uppercase;letter-spacing:.18em;font-weight:600;
  padding:6px 10px;border-radius:999px;
}
.product-badge.sale{background:var(--accent);color:#fff}
.product-wish{
  position:absolute;top:10px;right:10px;
  width:36px;height:36px;border-radius:50%;
  background:rgba(255,255,255,.9);backdrop-filter:blur(6px);
  display:flex;align-items:center;justify-content:center;
  opacity:0;transform:translateY(-4px);
  transition:all var(--t);
}
.product:hover .product-wish{opacity:1;transform:none}
.product-add{
  position:absolute;left:12px;right:12px;bottom:12px;
  background:var(--ink);color:#fff;
  padding:11px;border-radius:999px;
  font-size:12px;font-weight:600;letter-spacing:.06em;
  opacity:0;transform:translateY(8px);
  transition:all var(--t);
}
.product:hover .product-add{opacity:1;transform:none}
.product-add:hover{background:var(--accent)}

.product-cat{font-size:11px;text-transform:uppercase;letter-spacing:.16em;color:var(--muted);margin-bottom:6px}
.product-name{font-size:14px;font-weight:500;margin-bottom:4px}
.product-price{display:flex;gap:8px;align-items:baseline;font-size:14px}
.product-price .old{color:var(--muted);text-decoration:line-through;font-size:13px}
.product-price .now{color:var(--accent);font-weight:600}
.swatches{display:flex;gap:6px;margin-top:8px}
.swatch{width:12px;height:12px;border-radius:50%;border:1px solid var(--line)}

/* ---------- Deals ---------- */
.deals{
  background:var(--dark);
  color:#fff;
  padding:100px 0;
  margin-top:40px;
}
.deals h2{color:#fff}
.countdown{display:flex;gap:8px}
.countdown div{
  background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.1);
  padding:10px 14px;border-radius:10px;
  text-align:center;min-width:64px;
}
.countdown span{font-family:'Fraunces',serif;font-size:1.6rem;display:block;line-height:1;font-variant-numeric:tabular-nums}
.countdown label{font-size:9px;text-transform:uppercase;letter-spacing:.2em;color:rgba(255,255,255,.5);margin-top:4px;display:block}

.deals-grid{
  display:grid;
  grid-template-columns:1.4fr 1fr;
  gap:20px;
}
.deal-hero{
  position:relative;
  border-radius:var(--radius-lg);
  overflow:hidden;
  min-height:520px;
  display:flex;align-items:flex-end;
  isolation:isolate;
}
.deal-hero-img{
  position:absolute;inset:0;z-index:-1;
  background:linear-gradient(135deg,#7a6044 0%,#3a2a1c 100%);
  transition:transform .8s cubic-bezier(.2,.8,.2,1);
}
.deal-hero-img::after{
  content:'';position:absolute;inset:0;
  background:radial-gradient(circle at 70% 40%,rgba(200,81,44,.25),transparent 60%);
}
