.deal-hero-text{padding:48px;max-width:480px}
.deal-hero-text h3{font-size:2.4rem;color:#fff;margin:14px 0 10px}
.deal-hero-text p{color:rgba(255,255,255,.75);margin-bottom:18px}

.badge{
  display:inline-block;
  background:var(--accent);color:#fff;
  font-size:11px;font-weight:700;letter-spacing:.16em;
  padding:6px 12px;border-radius:999px;
  text-transform:uppercase;
}
.badge.alt{background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.18)}

.deals-side{display:grid;gap:20px}
.deal-card{
  position:relative;
  display:flex;align-items:center;gap:20px;
  background:rgba(255,255,255,.04);
  border:1px solid rgba(255,255,255,.08);
  border-radius:var(--radius-lg);
  overflow:hidden;
  padding:20px;
  transition:background var(--t),transform var(--t);
}
.deal-card:hover{background:rgba(255,255,255,.07);transform:translateY(-2px)}
.deal-img{
  width:140px;height:140px;flex-shrink:0;
  border-radius:14px;
  background-size:cover;
}
.deal-img-1{background:linear-gradient(135deg,#d8c2a4,#a48b6c)}
.deal-img-2{background:linear-gradient(135deg,#5b3f2a,#2a1a10)}
.deal-info h4{font-size:1.15rem;color:#fff;margin:10px 0 6px}
.deal-info p{font-size:13px;color:rgba(255,255,255,.6)}

/* ---------- Editorial ---------- */
.editorial{padding:100px 0}
.editorial-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  grid-template-rows:auto auto;
  gap:32px 24px;
}
.story-large{grid-column:span 1;grid-row:span 2;display:flex;flex-direction:column}
.story{display:flex;flex-direction:column;cursor:pointer}
.story-img{
  border-radius:var(--radius);
  background-size:cover;background-position:center;
  margin-bottom:18px;
  transition:transform .6s cubic-bezier(.2,.8,.2,1);
  aspect-ratio:4/3;
}
.story-large .story-img{aspect-ratio:3/4;flex-grow:1;min-height:400px}
.story:hover .story-img{transform:scale(.99)}
.story-img-1{background:linear-gradient(135deg,#d4c0a5,#7a6044)}
