+  border:1px solid rgba(255,255,255,.08);
+  border-radius:var(--radius-lg);
+  overflow:hidden;
+  padding:20px;
+  transition:background var(--t),transform var(--t);
+}
+.deal-card:hover{background:rgba(255,255,255,.07);transform:translateY(-2px)}
+.deal-img{
+  width:140px;height:140px;flex-shrink:0;
+  border-radius:14px;
+  background-size:cover;
+}
+.deal-img-1{background:linear-gradient(135deg,#d8c2a4,#a48b6c)}
+.deal-img-2{background:linear-gradient(135deg,#5b3f2a,#2a1a10)}
+.deal-info h4{font-size:1.15rem;color:#fff;margin:10px 0 6px}
+.deal-info p{font-size:13px;color:rgba(255,255,255,.6)}
+
