+.story{display:flex;flex-direction:column;cursor:pointer}
+.story-img{
+  border-radius:var(--radius);
+  background-size:cover;background-position:center;
+  margin-bottom:18px;
+  transition:transform .6s cubic-bezier(.2,.8,.2,1);
