+}
+.story-large .story-img{aspect-ratio:3/4;flex-grow:1;min-height:400px}
+.story:hover .story-img{transform:scale(.99)}
+.story-img-1{background:linear-gradient(135deg,#d4c0a5,#7a6044)}
+.story-img-2{background:linear-gradient(135deg,#b8a290,#5d4f42)}
+.story-img-3{background:linear-gradient(135deg,#a8b5b8,#4a5d63)}
+.story-img-4{background:linear-gradient(135deg,#dcc9b3,#8a7256)}
+.story-meta span{font-size:11px;text-transform:uppercase;letter-spacing:.18em;color:var(--muted);font-weight:500}
+.story-meta h3{margin:10px 0 8px;font-size:1.25rem;line-height:1.25}
+.story-large .story-meta h3{font-size:1.7rem;line-height:1.15}
+.story-meta p{font-size:14px;margin-bottom:14px}
+
+/* ---------- Values ---------- */
+.values{
+  background:var(--bg-alt);
+  padding:60px 0;
+  border-top:1px solid var(--line);
+  border-bottom:1px solid var(--line);
+}
+.values-grid{
+  display:grid;
