+.newsletter-form{
+  position:relative;z-index:1;
+  display:flex;gap:8px;flex-wrap:wrap;
+}
+.newsletter-form input{
+  flex:1;min-width:0;
+  padding:18px 22px;
+  background:rgba(255,255,255,.06);
