+}
+.footer-bottom a{margin-left:20px;transition:color var(--t)}
+.footer-bottom a:hover{color:var(--ink)}
+
+/* ---------- Toast ---------- */
+.toast{
+  position:fixed;bottom:30px;left:50%;
+  transform:translateX(-50%) translateY(100px);
