      <div class="product-img">
        <div class="product-img-inner" style="background-image:${p.gradient}"></div>
        ${p.badge?`<span class="product-badge ${p.badge==='Sale'?'sale':''}">${p.badge}</span>`:''}
        <button class="product-wish" aria-label="Add to wishlist">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9z"/></svg>
        </button>
        <button class="product-add" data-name="${p.name}">Add to bag — $${p.price}</button>
      </div>
      <span class="product-cat">${p.category}</span>
      <h4 class="product-name">${p.name}</h4>
      <div class="product-price">
