}
renderProducts();

// ---------- Filter tabs ----------
document.getElementById('filterTabs').addEventListener('click', e=>{
  if(e.target.tagName!=='BUTTON') return;
  document.querySelectorAll('#filterTabs button').forEach(b=>b.classList.remove('active'));
  e.target.classList.add('active');
  renderProducts(e.target.dataset.filter);
});

// ---------- Cart ----------
let cartCount = 0;
const cartCountEl = document.getElementById('cartCount');
const toast = document.getElementById('toast');
let toastTimer;

function showToast(msg){
  toast.textContent = msg;
  // re-trigger pseudo-element by toggling
  toast.classList.remove('show');
  void toast.offsetWidth;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>toast.classList.remove('show'), 2400);
}

document.addEventListener('click', e=>{
  const addBtn = e.target.closest('.product-add');
  if(addBtn){
    e.stopPropagation();
    cartCount++;
    cartCountEl.textContent = cartCount;
    cartCountEl.classList.add('show');
    showToast(`Added "${addBtn.dataset.name}" to bag`);
    cartCountEl.animate(
      [{transform:'scale(1)'},{transform:'scale(1.4)'},{transform:'scale(1)'}],
      {duration:300, easing:'ease-out'}
    );
  }
  const wishBtn = e.target.closest('.product-wish');
  if(wishBtn){
    e.stopPropagation();
    wishBtn.style.color = wishBtn.style.color === 'rgb(200, 81, 44)' ? '' : 'rgb(200, 81, 44)';
    showToast('Saved to wishlist');
  }
});

document.getElementById('cartBtn').addEventListener('click', ()=>{
  showToast(cartCount===0 ? 'Your bag is empty' : `You have ${cartCount} item${cartCount>1?'s':''} in your bag`);
});

// ---------- Header scroll ----------
const header = document.getElementById('header');
window.addEventListener('scroll', ()=>{
  header.classList.toggle('scrolled', window.scrollY > 10);
}, {passive:true});

// ---------- Mobile menu ----------
document.getElementById('menuBtn').addEventListener('click', ()=>{
  document.getElementById('mobileMenu').classList.toggle('open');
});

// ---------- Countdown ----------
const target = new Date();
target.setDate(target.getDate() + 3);
target.setHours(23, 59, 59, 0);

function tick(){
  const diff = Math.max(0, target - new Date());
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = n => String(n).padStart(2,'0');
  document.getElementById('d-d').textContent = pad(d);
  document.getElementById('d-h').textContent = pad(h);
  document.getElementById('d-m').textContent = pad(m);
  document.getElementById('d-s').textContent = pad(s);
}
tick();
setInterval(tick, 1000);

// ---------- Newsletter ----------
document.getElementById('newsletterForm').addEventListener('submit', e=>{
  e.preventDefault();
  const msg = document.getElementById('formMsg');
  msg.textContent = 'Thanks — check your inbox to confirm.';
  e.target.querySelector('input').value = '';
  setTimeout(()=>msg.textContent='', 5000);
});

// ---------- Reveal on scroll ----------
const io = new IntersectionObserver((entries)=>{
  entries.forEach(en=>{
    if(en.isIntersecting){
      en.target.style.opacity = 1;
      en.target.style.transform = 'none';
      io.unobserve(en.target);
    }
  });
},{threshold:.12});

document.querySelectorAll('.cat-card, .deal-card, .deal-hero, .story, .value').forEach(el=>{
  el.style.opacity = 0;
  el.style.transform = 'translateY(24px)';
  el.style.transition = 'opacity .8s cubic-bezier(.2,.8,.2,1), transform .8s cubic-bezier(.2,.8,.2,1)';
  io.observe(el);
});
